import{_ as o,o as a,c as e,a2 as d}from"./chunks/framework.DaAAbehN.js";const x=JSON.parse('{"title":"第 3 课：Codex vs 其他工具（不纠结版）","description":"","frontmatter":{},"headers":[],"relativePath":"modules/module-1/lesson-3.md","filePath":"modules/module-1/lesson-3.md"}'),r={name:"modules/module-1/lesson-3.md"};function l(i,t,h,s,n,u){return a(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="第-3-课-codex-vs-其他工具-不纠结版" tabindex="-1">第 3 课：Codex vs 其他工具（不纠结版） <a class="header-anchor" href="#第-3-课-codex-vs-其他工具-不纠结版" aria-label="Permalink to &quot;第 3 课：Codex vs 其他工具（不纠结版）&quot;">​</a></h1><blockquote><p>📌 <strong>学习目标</strong>：理解 Codex 与 ChatGPT、GitHub Copilot 的区别，知道什么时候该用什么工具<br> ⏱️ <strong>预计时长</strong>：10 分钟<br> 🎯 <strong>本节节奏</strong>：对比讲解为主</p></blockquote><hr><h2 id="一、先说结论" tabindex="-1">一、先说结论 <a class="header-anchor" href="#一、先说结论" aria-label="Permalink to &quot;一、先说结论&quot;">​</a></h2><p>如果你只想记住一句话，那就是：</p><blockquote><p><strong>Codex 能干的事比普通聊天 AI 多得多，它能直接操作你电脑上的文件。</strong></p></blockquote><p>其他的区别，我们慢慢聊。</p><hr><h2 id="二、codex-vs-chatgpt" tabindex="-1">二、Codex vs ChatGPT <a class="header-anchor" href="#二、codex-vs-chatgpt" aria-label="Permalink to &quot;二、Codex vs ChatGPT&quot;">​</a></h2><h3 id="关系说明" tabindex="-1">关系说明 <a class="header-anchor" href="#关系说明" aria-label="Permalink to &quot;关系说明&quot;">​</a></h3><p>Codex <strong>内置于</strong> ChatGPT。也就是说：</p><ul><li>你用 ChatGPT 时，如果切换到&quot;Advanced Search&quot;或&quot;Code Interpreter&quot;模式，你用的就是 Codex</li><li>你下载独立的 Codex 桌面 App，本质上也是 ChatGPT 的 Codex 功能，只是有了更好的界面</li></ul><p><strong>简单类比</strong>：ChatGPT 是一辆车，Codex 是这辆车的&quot;自动驾驶模式&quot;。</p><table tabindex="0"><thead><tr><th>特性</th><th>ChatGPT（普通聊天模式）</th><th>Codex（代码解释器/高级搜索模式）</th></tr></thead><tbody><tr><td>主要能力</td><td>回答问题、写文案、翻译</td><td>读文件、写代码、运行命令、操作文件系统</td></tr><tr><td>能否操作你的文件</td><td>❌ 不能</td><td>✅ 能（在工作区内）</td></tr><tr><td>能否执行代码</td><td>❌ 不能</td><td>✅ 能</td></tr><tr><td>典型使用场景</td><td>&quot;帮我写一封邮件&quot;</td><td>&quot;帮我分析这个 Excel 文件&quot;</td></tr></tbody></table><h3 id="小白记住一点就行" tabindex="-1">小白记住一点就行 <a class="header-anchor" href="#小白记住一点就行" aria-label="Permalink to &quot;小白记住一点就行&quot;">​</a></h3><ul><li>想<strong>聊天、问问题、写文案</strong> → 用 ChatGPT 普通模式</li><li>想<strong>让 AI 帮你干活</strong>（操作文件、写代码、做分析）→ 用 Codex</li></ul><hr><h2 id="三、codex-vs-github-copilot" tabindex="-1">三、Codex vs GitHub Copilot <a class="header-anchor" href="#三、codex-vs-github-copilot" aria-label="Permalink to &quot;三、Codex vs GitHub Copilot&quot;">​</a></h2><p>这是最容易混淆的一对。</p><h3 id="github-copilot-是什么" tabindex="-1">GitHub Copilot 是什么？ <a class="header-anchor" href="#github-copilot-是什么" aria-label="Permalink to &quot;GitHub Copilot 是什么？&quot;">​</a></h3><p>Copilot 是一个<strong>代码补全插件</strong>，它运行在你的代码编辑器里（比如 VS Code）。</p><ul><li>你在写代码时，它猜你想写什么，帮你补全下一行</li><li>它<strong>不能</strong>独立完成任务——你必须自己写代码、自己调试、自己测试</li><li>它<strong>不能</strong>操作你的文件——它只能在编辑器里给你建议</li></ul><h3 id="codex-是什么" tabindex="-1">Codex 是什么？ <a class="header-anchor" href="#codex-是什么" aria-label="Permalink to &quot;Codex 是什么？&quot;">​</a></h3><p>Codex 是一个<strong>独立的智能体</strong>。</p><ul><li>你告诉它&quot;帮我做一个网页&quot;，它会自己读文件、写代码、保存文件</li><li>它<strong>能</strong>独立完成从需求到交付的全过程</li><li>它<strong>能</strong>操作你的文件系统</li></ul><h3 id="对比表格" tabindex="-1">对比表格 <a class="header-anchor" href="#对比表格" aria-label="Permalink to &quot;对比表格&quot;">​</a></h3><table tabindex="0"><thead><tr><th>特性</th><th>GitHub Copilot</th><th>Codex</th></tr></thead><tbody><tr><td>工作位置</td><td>代码编辑器内（VS Code 等）</td><td>独立应用 / 命令行</td></tr><tr><td>你需要会编程吗？</td><td>✅ 需要至少看得懂代码</td><td>❌ 不需要，用自然语言即可</td></tr><tr><td>任务粒度</td><td>单行/单函数级别的补全</td><td>完整功能/完整项目</td></tr><tr><td>能否操作文件</td><td>❌ 不能</td><td>✅ 能</td></tr><tr><td>能否运行代码</td><td>❌ 不能</td><td>✅ 能</td></tr><tr><td>典型用户</td><td>程序员</td><td>任何人</td></tr></tbody></table><h3 id="小白记住一点就行-1" tabindex="-1">小白记住一点就行 <a class="header-anchor" href="#小白记住一点就行-1" aria-label="Permalink to &quot;小白记住一点就行&quot;">​</a></h3><ul><li><strong>Copilot = 帮你补全代码的&quot;副驾驶&quot;</strong></li><li><strong>Codex = 帮你完成整个任务的&quot;实习生&quot;</strong></li></ul><hr><h2 id="四、codex-vs-传统自动化工具" tabindex="-1">四、Codex vs 传统自动化工具 <a class="header-anchor" href="#四、codex-vs-传统自动化工具" aria-label="Permalink to &quot;四、Codex vs 传统自动化工具&quot;">​</a></h2><p>你可能听说过 RPA（机器人流程自动化）、Excel 宏、Apple Shortcuts 之类的工具。</p><h3 id="传统自动化工具的问题" tabindex="-1">传统自动化工具的问题 <a class="header-anchor" href="#传统自动化工具的问题" aria-label="Permalink to &quot;传统自动化工具的问题&quot;">​</a></h3><ul><li>需要<strong>预先设计好流程</strong>，灵活性差</li><li>一旦需求变化，就要重新配置</li><li>通常需要编程知识或专门的工具</li></ul><h3 id="codex-的优势" tabindex="-1">Codex 的优势 <a class="header-anchor" href="#codex-的优势" aria-label="Permalink to &quot;Codex 的优势&quot;">​</a></h3><ul><li><strong>用自然语言描述需求</strong>，不需要预先设计流程</li><li><strong>灵活调整</strong>——觉得哪里不对，告诉它改就行</li><li><strong>不需要编程知识</strong></li></ul><h3 id="举例" tabindex="-1">举例 <a class="header-anchor" href="#举例" aria-label="Permalink to &quot;举例&quot;">​</a></h3><table tabindex="0"><thead><tr><th>任务</th><th>传统方式</th><th>Codex 方式</th></tr></thead><tbody><tr><td>批量重命名文件</td><td>写一个 Python 脚本，或者用专门的批量重命名软件</td><td>说：&quot;把这些文件名里的&#39;IMG_&#39;改成&#39;Photo_&#39;&quot;</td></tr><tr><td>合并多个 Excel</td><td>用 Power Query 或 VBA</td><td>说：&quot;把这三个 Excel 文件的数据合并到一个表里&quot;</td></tr></tbody></table><hr><h2 id="五、本节的-一句话总结" tabindex="-1">五、本节的&quot;一句话总结&quot; <a class="header-anchor" href="#五、本节的-一句话总结" aria-label="Permalink to &quot;五、本节的&quot;一句话总结&quot;&quot;">​</a></h2><blockquote><p><strong>Codex 不是聊天工具，不是代码补全工具，不是传统自动化工具。它是一个能听懂人话、能操作你电脑的智能助手。</strong></p></blockquote><hr><h2 id="六、课后思考" tabindex="-1">六、课后思考 <a class="header-anchor" href="#六、课后思考" aria-label="Permalink to &quot;六、课后思考&quot;">​</a></h2><ol><li>你之前用过哪些工具来尝试自动化办公？Codex 和它们比有什么不一样？</li><li>你觉得在什么场景下你会优先选择 Codex，而不是其他工具？</li></ol><hr><h2 id="七、下一步" tabindex="-1">七、下一步 <a class="header-anchor" href="#七、下一步" aria-label="Permalink to &quot;七、下一步&quot;">​</a></h2><p><a href="./../module-2/lesson-4.html">→ 进入模块二：上手准备</a></p>',47)])])}const b=o(r,[["render",l]]);export{x as __pageData,b as default};
